export function installAquatic(data){if(data.species.some(s=>s.id==='376'))return;data.species.push(...AQUATIC_SPECIES);data.moves.push(...AQUATIC_MOVES);for(const species_id of ['378','379','380','381','382','383','384'])AQUATIC_LEARNSETS.push({species_id,move_id:species_id==='381'?106:species_id>='382'?175:340,level:12,method:'LEVEL_UP',expansion:true,identity:true,identity_core:true,approvedAquatic:true});for(const l of AQUATIC_LEARNSETS){l.name=data.moves.find(m=>m.id===l.move_id).name;l.provenance=provenance;data.learnsets.push(l);data.authoredLearnsets?.push({...l});}for(const s of AQUATIC_SPECIES)data.assets.push({id:s.id,source:'dist/assets/approved-aquatic/'+({'376':'shark','377':'shark','378':'narwhal','379':'narwhal','380':'narwhal','381':'sunfish','382':'manta','383':'manta','384':'manta'}[s.id])+'.png',runtime:'assets/approved-aquatic/'+({'376':'shark','377':'shark','378':'narwhal','379':'narwhal','380':'narwhal','381':'sunfish','382':'manta','383':'manta','384':'manta'}[s.id])+'.png'});}
export function aquaticEncounterRoute(route){if(route.aquaticExpanded)return route;const extra={coralGrotto:['376','381'],moonlitDepths:['378'],reedSanctuary:['382']}[route.room];if(!extra)return route;return {...route,aquaticExpanded:true,tables:route.tables.map(t=>{const slots=t.slots.map(s=>({...s}));slots.reduce((a,b)=>a.weight>b.weight?a:b).weight-=extra.length;const level=slots[0];for(const species_id of extra)slots.push({species_id,min_level:level.min_level,max_level:level.max_level,weight:1,rarity:'Rare',authoredSlot:true,approvedAquatic:true});return {...t,slots};})};}
